// MARK: Significant events

/// A significant time of day (a string enumeration, as in the Swift API).
public struct HMSignificantEvent: RawRepresentable, Hashable, Codable, Sendable {
    public let rawValue: String
    public init(rawValue: String) { self.rawValue = rawValue }
    public init(_ rawValue: String) { self.rawValue = rawValue }
    /// iOS 9.0.
    public static let sunrise = HMSignificantEvent(rawValue: "sunrise")
    /// iOS 9.0.
    public static let sunset = HMSignificantEvent(rawValue: "sunset")
}
